// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#1e3a8a", "#d97706", "#f59e0b", "#3b82f6", "#172554"];
var speedMult = 2.5;
var lineScale = 1.3;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by '241118a' by 'takawo' ===
