// === Tab: mySketch ===
function setup() {
  createCanvas(800, 800, WEBGL);
  // ortho(-width/2,width/2,-height/2,height/2,-5000,5000);
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

  background(10, 10, 15);
  rotateX(PI / 2);
  orbitControl();
  stroke(0);
  for (let v = 0; v < TWO_PI; v += TWO_PI / 20) {
		push();
		// rotateY(v);
    beginShape(QUAD_STRIP);
    for (let y = -height; y < height; y += height / 20) {
      let r = map(y, -height, height, 0, 400);
      let theta = v + map(y, -height, height, 0, TWO_PI);
      let t = TWO_PI / 30;

      let x1 = cos(theta - t) * r;
      let z1 = sin(theta - t) * r;
      let x2 = cos(theta + t) * r;
      let z2 = sin(theta + t) * r;
      noStroke();
      fill(getColor(theta - t, y / 100 + (frameCount * speedMult) / 50));
      vertex(x1, y, z1);
      fill(getColor(theta + t, y / 100 - (frameCount * speedMult) / 50));
      vertex(x2, y, z2);
    }
    endShape();
		pop();
  }
}

function getColor(angle, time) {
  const c1 = [1, 0, 0],
    f1 = 1.0,
    p1 = 150;
  const c2 = [0, 1, 0],
    f2 = 1.0,
    p2 = 180;
  const c3 = [0, 0, 1],
    f3 = 1.0,
    p3 = 210;

  const s1 = map(cos(angle * f1 + time + p1), -1, 1, 0, 1);
  const s2 = map(cos(angle * f2 + time + p2), -1, 1, 0, 1);
  const s3 = map(cos(angle * f3 + time + p3), -1, 1, 0, 1);

  var r = s1 * c1[0] + s2 * c2[0] + s3 * c3[0];
  const g = s1 * c1[1] + s2 * c2[1] + s3 * c3[1];
  const b = s1 * c1[2] + s2 * c2[2] + s3 * c3[2];

  return color(r * 255, g * 255, b * 255);
}
